package com.icescream.infera.ui

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.itemsIndexed
import androidx.compose.foundation.lazy.rememberLazyListState
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.compose.foundation.background // <-- Importa el background correcto
import kotlinx.coroutines.*
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject

val client = OkHttpClient()

fun sendMessageToGeminiApi(message: String, callback: (String) -> Unit) {
 val body = JSONObject(mapOf("prompt" to message)).toString()
 .toRequestBody("application/json".toMediaType())
 val request = Request.Builder()
 .url("http://192.168.100.2:3001/api/chat") // Cambia la IP si necesitas acceder desde un teléfono
 .post(body)
 .build()

 CoroutineScope(Dispatchers.IO).launch {
 client.newCall(request).execute().use { response ->
 val bodyStr = response.body?.string() ?: ""
 val texto = try {
 JSONObject(bodyStr).getString("response")
 } catch (_: Exception) {
 "¡Hubo un problema en el servidor!"
 }
 withContext(Dispatchers.Main) {
 callback(texto)
 }
 }
 }
}

// Modelo de mensaje
data class ChatMessage(val text: String, val isUser: Boolean)

@Composable
fun ChatBotScreen(onBack: () -> Unit) {
 var prompt by remember { mutableStateOf("") }
 var iaResponse by remember { mutableStateOf("") }
 var isLoading by remember { mutableStateOf(false) }

 Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.TopCenter) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(24.dp),
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text("Gemini Playground", style = MaterialTheme.typography.headlineMedium)
 Spacer(Modifier.height(24.dp))
 TextField(
 value = prompt,
 onValueChange = { prompt = it },
 placeholder = { Text("Escribe tu pregunta...") },
 modifier = Modifier.fillMaxWidth(0.95f)
 )
 Spacer(Modifier.height(16.dp))
 Button(
 onClick = {
 val userPrompt = prompt.trim()
 if (userPrompt.isEmpty()) return@Button
 isLoading = true
 iaResponse = ""
 sendMessageToGeminiApi(userPrompt) { reply ->
 iaResponse = reply
 isLoading = false
 }
 },
 enabled = !isLoading && prompt.isNotBlank()
 ) {
 Text("Enviar")
 }
 Spacer(Modifier.height(32.dp))
 Text(
 when {
 isLoading -> "Cargando respuesta..."
 iaResponse.isNotEmpty() -> iaResponse
 else -> "Aquí verás la respuesta de la IA."
 },
 style = MaterialTheme.typography.bodyLarge
 )
 }
 // Botón regresar en la esquina superior
 Button(
 onClick = onBack,
 modifier = Modifier
 .align(Alignment.TopStart)
 .padding(16.dp)
 ) {
 Text("Regresar")
 }
 }
}

@Composable
fun UserAvatar() {
 Box(
 modifier = Modifier
 .size(32.dp)
 .background(MaterialTheme.colorScheme.primary, shape = MaterialTheme.shapes.small),
 contentAlignment = Alignment.Center
 ) {
 Text("Tú", color = Color.White, style = MaterialTheme.typography.bodySmall)
 }
}

@Composable
fun BotAvatar() {
 Box(
 modifier = Modifier
 .size(32.dp)
 .background(MaterialTheme.colorScheme.secondary, shape = MaterialTheme.shapes.small),
 contentAlignment = Alignment.Center
 ) {
 Text("IA", color = Color.White, style = MaterialTheme.typography.bodySmall)
 }
}

```
