require('dotenv').config();
const express = require('express');
const axios = require('axios');
const cors = require('cors');

const app = express();
app.use(express.json());
app.use(cors());

const PORT = 3001;
const API_KEY = process.env.GEMINI_API_KEY;

app.post('/api/chat', async (req, res) => {
 const { prompt } = req.body;

 const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${API_KEY}`;

 try {
 const response = await axios.post(apiUrl, {
 contents: [{ parts: [{ text: prompt }] }],
 });

 // Gemini generalmente responde texto plano; NO es necesario hacer JSON.parse
 const botResponseText = response.data.candidates[0].content.parts[0].text;

 res.json({
 response: botResponseText, // texto directo de la IA
 });

 } catch (error) {
 console.error('Error al llamar a la API de IA:', error.response ? error.response.data : error.message);
 res.status(500).json({
 response: "Lo siento, tuve un problema técnico. ¿Podrías intentarlo de nuevo?",
 });
 }
});

app.listen(PORT, () => {
 console.log(`✅ Servidor intermediario corriendo en http://localhost:${PORT}`);
});
