const axios = require('axios');
const cors = require('cors');

const app = express();
app.use(express.json());
app.use(cors());

const PORT = 3001;
const API_KEY = process.env.GEMINI_API_KEY; // Tu API KEY se lee del archivo .env

app.post('/api/chat', async (req, res) => {
 const { prompt } = req.body;

 // Verifica que llega un prompt
 if (!prompt || typeof prompt !== 'string') {
 return res.status(400).json({
 response: "Prompt inválido o no enviado.",
 });
 }

 const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${API_KEY}`;

 try {
 // Llamada a Gemini
 const response = await axios.post(apiUrl, {
 contents: [{ parts: [{ text: prompt }] }],
 });

 // Logging de la respuesta raw
 console.log('Respuesta raw Gemini:', response.data);

 // Obtiene el texto de la IA (verifica estructura antes de acceder)
 const candidates = response.data.candidates;
 let botResponseText = "No se pudo obtener respuesta de la IA.";
 if (
 Array.isArray(candidates) &&
 candidates[0] &&
 candidates[0].content &&
 candidates[0].content.parts &&
 candidates[0].content.parts[0] &&
 candidates[0].content.parts[0].text
 ) {
 botResponseText = candidates[0].content.parts[0].text;
 }

 res.json({
 response: botResponseText,
 });

 } catch (error) {
 // Logging detallado de error
 if (error.response) {
 console.error('Error IA:', error.response.data);
 } else {
 console.error('Error IA:', error.message);
 }
 res.status(500).json({
 response: "Lo siento, tuve un problema técnico. ¿Podrías intentarlo de nuevo?",
 });
 }
});

app.listen(PORT, () => {
 console.log(`✅ Servidor intermediario corriendo en http://localhost:${PORT}`);
});
```

---

### Recuerda:
- Tu archivo `.env` (en la misma carpeta que `server.js`) debe tener:
 ```
 GEMINI_API_KEY=TU_API_KEY_AQUI
 ```
- Debes instalar las dependencias si no están:
 ```bash
 npm install express axios cors dotenv
 ```

---

Con esto, el backend acepta solicitudes POST sobre `/api/chat`, llama a Gemini 2.0 Flash, y devuelve la respuesta al cliente móvil. 
Incluye control de entrada, manejo robusto de errores y logs para depuración.

