package com.icescream.infera.ui

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.itemsIndexed
import androidx.compose.foundation.lazy.rememberLazyListState
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.*
import okhttp3.*
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject

val client = OkHttpClient()

fun sendMessageToGeminiApi(message: String, callback: (String) -> Unit) {
 val body = JSONObject(mapOf("prompt" to message)).toString()
 .toRequestBody("application/json".toMediaType())
 val request = Request.Builder()
 .url("http://192.168.100.2:3001/api/chat") // Cambia la IP si necesitas acceder desde un teléfono
 .post(body)
 .build()

 CoroutineScope(Dispatchers.IO).launch {
 client.newCall(request).execute().use { response ->
 val bodyStr = response.body?.string() ?: ""
 val texto = try {
 JSONObject(bodyStr).getString("response")
 } catch (_: Exception) {
 "¡Hubo un problema en el servidor!"
 }
 withContext(Dispatchers.Main) {
 callback(texto)
 }
 }
 }
}

// Modelo de mensaje
data class ChatMessage(val text: String, val isUser: Boolean)

@Composable
fun ChatBotScreen(onBack: () -> Unit) {
 var message by rememberSaveable { mutableStateOf("") }
 val chatMessages = remember { mutableStateListOf<ChatMessage>() }
 var isBotTyping by remember { mutableStateOf(false) }
 val listState = rememberLazyListState()

 // Autoscroll cada vez que cambia chatMessages
 LaunchedEffect(chatMessages.size) {
 if (chatMessages.isNotEmpty()) {
 listState.animateScrollToItem(chatMessages.size - 1)
 }
 }

 Box(Modifier.fillMaxSize()) {
 Column(modifier = Modifier.fillMaxSize()) {
 Text(
 "ChatBot Gemini",
 style = MaterialTheme.typography.headlineMedium,
 modifier = Modifier
 .align(Alignment.CenterHorizontally)
 .padding(8.dp)
 )
 Divider()

 // Lista de mensajes con avatar y alineación
 LazyColumn(
 state = listState,
 modifier = Modifier
 .weight(1f)
 .fillMaxWidth()
 .padding(8.dp)
 ) {
 itemsIndexed(chatMessages) { _, msg ->
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(vertical = 4.dp),
 horizontalArrangement = if (msg.isUser) Arrangement.End else Arrangement.Start,
 verticalAlignment = Alignment.Bottom
 ) {
 if (!msg.isUser) {
 BotAvatar()
 Spacer(Modifier.width(4.dp))
 }
 Surface(
 color = if (msg.isUser) MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
 else MaterialTheme.colorScheme.inverseSurface.copy(alpha = 0.18f),
 shape = MaterialTheme.shapes.medium
 ) {
 Text(
 text = msg.text,
 modifier = Modifier.padding(10.dp),
 color = if (msg.isUser) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface
 )
 }
 if (msg.isUser) {
 Spacer(Modifier.width(4.dp))
 UserAvatar()
 }
 }
 }

 // Indicador de "bot está escribiendo"
 if (isBotTyping) {
 item {
 Row(
 Modifier.fillMaxWidth(),
 verticalAlignment = Alignment.CenterVertically
 ) {
 BotAvatar()
 Spacer(Modifier.width(4.dp))
 Text(
 "...escribiendo respuesta",
 color = Color.Gray,
 modifier = Modifier.padding(8.dp)
 )
 }
 }
 }
 }

 // Zona enviar mensajes
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(8.dp)
 ) {
 TextField(
 value = message,
 onValueChange = { message = it },
 modifier = Modifier.weight(1f),
 placeholder = { Text("Escribe un mensaje...") }
 )
 Spacer(Modifier.width(8.dp))
 Button(
 onClick = {
 val userMsg = message.trim()
 if (userMsg.isNotEmpty()) {
 chatMessages.add(ChatMessage(userMsg, true))
 message = ""
 isBotTyping = true
 sendMessageToGeminiApi(userMsg) { reply ->
 isBotTyping = false
 chatMessages.add(ChatMessage(reply, false))
 }
 }
 },
 enabled = !isBotTyping
 ) {
 Text("Enviar")
 }
 }
 }

 // Botón regresar.
 Button(
 onClick = onBack,
 modifier = Modifier
 .align(Alignment.TopStart)
 .padding(16.dp)
 ) {
 Text("Regresar")
 }
 }
}

@Composable
fun UserAvatar() {
 Box(
 modifier = Modifier
 .size(32.dp)
 .background(MaterialTheme.colorScheme.primary, shape = MaterialTheme.shapes.small),
 contentAlignment = Alignment.Center
 ) {
 Text("Tú", color = Color.White, style = MaterialTheme.typography.bodySmall)
 }
}

@Composable
fun BotAvatar() {
 Box(
 modifier = Modifier
 .size(32.dp)
 .background(MaterialTheme.colorScheme.secondary, shape = MaterialTheme.shapes.small),
 contentAlignment = Alignment.Center
 ) {
 Text("IA", color = Color.White, style = MaterialTheme.typography.bodySmall)
 }
}

