 res.status(500).json({
 response: "Lo siento, tuve un problema técnico. ¿Podrías intentarlo de nuevo?",
 });
 }
});

app.listen(PORT, () => {
 console.log(`✅ Servidor intermediario corriendo en http://localhost:${PORT}`);
});
